import{_ as a,H as t,f as p,i as l}from"./chunks/framework.BH2BK_3i.js";const d=JSON.parse('{"title":"07-遗留系统现代化的五种策略：重构还是重写？这是一个问题","description":"","frontmatter":{},"headers":[{"level":2,"title":"遗留系统现代化的五种策略","slug":"遗留系统现代化的五种策略","link":"#遗留系统现代化的五种策略","children":[{"level":3,"title":"Encapsulate","slug":"encapsulate","link":"#encapsulate","children":[]},{"level":3,"title":"Replatform","slug":"replatform","link":"#replatform","children":[]},{"level":3,"title":"Rehost","slug":"rehost","link":"#rehost","children":[]},{"level":3,"title":"Refactor/Rearchitect","slug":"refactor-rearchitect","link":"#refactor-rearchitect","children":[]},{"level":3,"title":"Rebuild/Replace","slug":"rebuild-replace","link":"#rebuild-replace","children":[]},{"level":3,"title":"其他策略","slug":"其他策略","link":"#其他策略","children":[]}]},{"level":2,"title":"你应该选择什么样的策略？","slug":"你应该选择什么样的策略","link":"#你应该选择什么样的策略","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"遗留系统现代化实战/07-遗留系统现代化的五种策略：重构还是重写？这是一个问题.md","filePath":"遗留系统现代化实战/07-遗留系统现代化的五种策略：重构还是重写？这是一个问题.md","lastUpdated":1795561327000}'),r={name:"遗留系统现代化实战/07-遗留系统现代化的五种策略：重构还是重写？这是一个问题.md"};function i(o,e,c,E,n,h){return t(),p("div",null,[...e[0]||(e[0]=[l('<h1 id="_07-遗留系统现代化的五种策略-重构还是重写-这是一个问题" tabindex="-1">07-遗留系统现代化的五种策略：重构还是重写？这是一个问题 <a class="header-anchor" href="#_07-遗留系统现代化的五种策略-重构还是重写-这是一个问题" aria-label="Permalink to &quot;07-遗留系统现代化的五种策略：重构还是重写？这是一个问题&quot;">​</a></h1><p>你好，我是姚琪琳。</p><p>从今天开始，我们正式进入模式篇的学习。这一部分我会带你学习代码、架构、DevOps、团队结构四个现代化中的各种模式，这些模式是我们实战的理论基础，希望你能牢牢掌握。</p><p>不过深入学习这些模式前，今天我们先从重构和重写的“两难”问题说起。到底是重构，还是重写？这是一个困扰着很多团队的问题。</p><p>重构吧，遗留系统积重难返，重构之路遥遥无期，三年、五年时间，可能也只是刚开了个头，还不如重写。</p><p>但重写就真的比重构好吗？遗留系统中最难获取的就是业务知识。当你问起一块业务时，得到的回答往往是：“没有文档”、“没人知道”或者“只能看代码”……没有业务，或者说没有需求，怎么可能构建出来一个新的系统呢？</p><p>那我们到底应该如何应对呢？除了重构和重写，还有没有其他方式呢？</p><h2 id="遗留系统现代化的五种策略" tabindex="-1">遗留系统现代化的五种策略 <a class="header-anchor" href="#遗留系统现代化的五种策略" aria-label="Permalink to &quot;遗留系统现代化的五种策略&quot;">​</a></h2><p>Gartner 在 19 年曾经有一篇报道，提出了遗留系统现代化的七种方案。我把这七种方案做了整合，把它们整理成后面这五种策略。它们各有各的特点，而且分别对应不同场景，你要根据项目自身情况选择不同的策略或组合。然后，再应用后面要讲的模式来落地。</p><h3 id="encapsulate" tabindex="-1">Encapsulate <a class="header-anchor" href="#encapsulate" aria-label="Permalink to &quot;Encapsulate&quot;">​</a></h3><p>第一种策略是 Encapsulate，也就是将遗留系统中的数据或者功能封装成 API，供外部调用。</p><p>我们在第一节课里提到过，遗留系统中蕴含着丰富的数据资产，但是因为技术和工具落后，导致它难以与新系统集成，这些数据被封印在遗漏系统中，成了数据孤岛。比如早期的银行或民航软件，很多都是部署在大型机上的。企业非常希望开发手机 App，这样才能更好地为客户服务，但却很难访问到主机上的这些数据。</p><p>同样地，遗留系统中还有一些功能十分重要，其他外部系统需要这些能力来构建业务。比如一些公文流转的工作流，可能构建在基于 Lotus Notes 的办公系统中，但如果企业想要开发移动办公 App，并在 App 中复用这套工作流，也是困难重重。</p><p>问题虽然棘手，但事到临头，工程师们总要想办法应对。结合刚才说的情况，我们可以封装这些数据和功能，形成 API，供这些移动 App 或其他外部系统使用。如果遗留系统本身就是基于 Web 的，可以在 Web 系统上直接构建 API；如果不是，可以选择构建一个全新的 WebAPI 来部署并提供服务。</p><p>这样做的好处是，以较低的成本和风险，尽可能满足外部系统的需求。你无需对遗留系统做较大的修改，只是增加一些 API 而已。遗留系统本身不会被优化，但它可以通过这些 API 对外提供能力。</p><p>还有一种情况，我也建议你使用封装的策略，那就是当你有一个第三方系统，希望扩展它的功能，但只能访问它的数据库，却无法修改代码的时候。</p><p>这时有些团队采用的方式就是直接连它的数据库，并在已有的系统中基于这些数据构建新的功能。我不建议你这么做，直接连数据库固然简单，但由于你可以访问它所有的表和列，距离混乱也就剩一步之遥了。</p><p>我建议你基于这个第三方系统的数据库构建一个 Web API，来向其他的系统提供你想提供的数据和功能，而不是暴露全部的数据。</p><p>我这里也稍微剧透下，封装的策略落到具体应用的时候，衍生出了很多相关模式，比如数据API 模式、功能 API 模式等等。我会在后面的课里再详细展开。</p><h3 id="replatform" tabindex="-1">Replatform <a class="header-anchor" href="#replatform" aria-label="Permalink to &quot;Replatform&quot;">​</a></h3><p>第二种策略是 Replatform，也就是替换运行时平台。这种策略不需要对代码大动干戈，只需要改动很小一部分。到了新的平台后，软件的功能和特性仍然保持不变。</p><p>比如，很多银行或民航软件还是基于 COBOL 的主机系统，把它们从大型机上迁移到 Linux 或Windows 环境，就会甩掉昂贵的主机成本。</p><p>再比如，早年间开始构建的系统，由于种种原因，很多是基于商业软件的，想升级，就要花一大笔预算。很多企业为了节省这部分开支，会尽量避免升级，也导致系统最终变成了遗留系统。你可以通过 Replatform 策略来解除对商业软件的依赖，例如用 Tomcat 来替换WebLogic。</p><p>或者像.NET 这种技术栈，也十分有必要从.NET Framework 迁移到.NET Core 或者.NET 5。而 Python 从 2 升级到 3、JDK 的大版本升级等等，也都属于 Replatform。</p><p>在使用 Replatform 时，你只需要对代码做少量更改，以适配新的平台。这样，只通过较小的成本就可以降低基础设施的成本，并提高性能。</p><p>还有一种迁移我认为也可以看做是 Replatform，虽然它并不是替换运行时平台。那就是迁移代码版本管理工具。比如你把代码从 SVN 迁移到 Git 中，不需要修改任何功能代码，但却可以享受新的代码管理平台带来的好处。</p><h3 id="rehost" tabindex="-1">Rehost <a class="header-anchor" href="#rehost" aria-label="Permalink to &quot;Rehost&quot;">​</a></h3><p>第三种策略是 Rehost，也就是将应用程序或组件部署到其他基础设施中，如虚拟主机、容器或云。这种策略完全不需要修改代码，而只需要迁移部署的环境，甚至都不需要重新编译，因此这种迁移方法也有个很形象的别名，叫做“lift and shift”，就是原封不动地拎起来，转移到别的地方去。</p><p>我举个例子来说明，如果你的公司有一个 SAP 的 ERP 系统，可以将它从本地的数据中心迁移到 AWS 或 GCP 中。</p><p>Rehost 可以让你在完全不修改已有系统的情况下，快速上云，体验云环境带来的弹性、安全性和高性能，并且迁移过程也能做到很平滑。然而由于没有任何适配，也就无法充分利用云原生的优势，因此还需要对系统内部的代码和架构做进一步调整，比如将单体架构拆分为可以独立运维的微服务。</p><h3 id="refactor-rearchitect" tabindex="-1">Refactor/Rearchitect <a class="header-anchor" href="#refactor-rearchitect" aria-label="Permalink to &quot;Refactor/Rearchitect&quot;">​</a></h3><p>第四种策略是 Refactor 和 Rearchitect，它们是指在不改变系统外部行为的前提下，对代码或架构进行调整、优化，以偿还拖欠已久的技术债务、改善非功能需求、提升系统健康度。</p><p>Refactor 主要是指代码级别的重构，比如你可能用 Sonar 等代码扫描工具，扫描出了很多代码坏味道、缺陷或隐患，修复这些问题的过程就属于 Refactor。这和我们平时说的代码重构基本上是一个意思。</p><p>Rearchitect 是指架构级别的重构，它包含两层意思。第一层比较好理解，就是指从单体架构到分布式架构的这种架构调整。第二层是指不改变部署单元之间的关系，而是对单个或多个部署单元内部进行模块化或分层重构。由于这种模块化和分层也会涉及很多代码的调整，所以这种 Rearchitect 往往会和 Refactor 同时进行。</p><p>后面你学到代码和架构现代化的内容时，会看到很多 Refactor/Rearchitect 相关的模式。这些也往往是遗留系统现代化中最有挑战，也最有意思的部分。</p><h3 id="rebuild-replace" tabindex="-1">Rebuild/Replace <a class="header-anchor" href="#rebuild-replace" aria-label="Permalink to &quot;Rebuild/Replace&quot;">​</a></h3><p>第五种策略是 Rebuild 和 Replace，都是指对遗留系统进行替换。它们两个替换的范围和程度不同。Rebuild 可能是对应用程序的某个组件或某个服务的重新设计或重写，但会保留其原有的业务范围和业务规则。而 Replace 是指彻底淘汰应用程序的所有组件，去构建或购买新的软件，同时会考虑添加新的业务需求或移除某些旧的业务需求。</p><p>我在第一节课提到过，遗留系统中的业务知识是严重缺失的，不仅没有遗留下来的文档供我们查阅，也没有任何一个人能说清楚全部的业务细节。在这样的基础上实施 Rebuild 或Replace，风险和成本都是相当高的，但相对来说，收益也是最高的，一旦替换成功，就可以彻底摆脱原来的遗留系统了。</p><p>下图是对上面五种策略的一个总结，你可以从中看出它们的收益、风险和成本（用面积表示）：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%81%97%E7%95%99%E7%B3%BB%E7%BB%9F%E7%8E%B0%E4%BB%A3%E5%8C%96%E5%AE%9E%E6%88%98/images/07-%25E9%2581%2597%25E7%2595%2599%25E7%25B3%25BB%25E7%25BB%259F%25E7%258E%25B0%25E4%25BB%25A3%25E5%258C%2596%25E7%259A%2584%25E4%25BA%2594%25E7%25A7%258D%25E7%25AD%2596%25E7%2595%25A5/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%81%97%E7%95%99%E7%B3%BB%E7%BB%9F%E7%8E%B0%E4%BB%A3%E5%8C%96%E5%AE%9E%E6%88%98/images/07-%25E9%2581%2597%25E7%2595%2599%25E7%25B3%25BB%25E7%25BB%259F%25E7%258E%25B0%25E4%25BB%25A3%25E5%258C%2596%25E7%259A%2584%25E4%25BA%2594%25E7%25A7%258D%25E7%25AD%2596%25E7%2595%25A5/1.png" alt=""></a></p><h3 id="其他策略" tabindex="-1">其他策略 <a class="header-anchor" href="#其他策略" aria-label="Permalink to &quot;其他策略&quot;">​</a></h3><p>除了上面的几种策略以外，对于遗留系统来说还有一些应对策略可以选择。不过由于不涉及到代码、架构或运行环境的变更，我没有把它们作为遗留系统现代化的策略。</p><p>其中一种是 Retain，即保持系统当前的状态不做任何修改或更新。对于尚可满足使用的遗留系统来说，这无疑是风险和成本最低的策略。我在第五节课说过，使用人数不多、需求很少、只需要一两个人维护的遗留系统，就可以使用这种策略。</p><p>还有一种是 Retire，就是评估完工作量、使用情况和业务价值之后，选择完全停止使用的一种策略。有的时候系统已经没有什么人用了，或者类似的功能在其他系统中可以替代，你就可以选择让这个旧系统彻底退休了。</p><h2 id="你应该选择什么样的策略" tabindex="-1">你应该选择什么样的策略？ <a class="header-anchor" href="#你应该选择什么样的策略" aria-label="Permalink to &quot;你应该选择什么样的策略？&quot;">​</a></h2><p>面对如此眼花缭乱的策略，你恐怕更加无所适从了吧？别担心，接下来我就来帮你梳理一下如何选择。</p><p>到底是 Replatform 还是 Rehost？是 Refactor 还是 Rebuild？是 Rearchitect 还是 Replace？其实，我们还是要依据目标和系统现状做判断。</p><p>先看最终目标，第五节课我列出了企业遗留系统现代化的四个目标，即业务敏捷、运营效率、客户洞见、系统韧性与弹性。</p><p>对于业务敏捷来说，Replatform 和 Rehost 通过替换运行时环境和上云可以提升部署频率，特别是 Rehost 可以显著提升系统在遇到故障时的恢复时间；Refactor/Rearchitect 通过改善代码和架构的质量，可以缩短需求交付周期，减少线上问题数量；而 Rebuild/Replace 由于在某种程度上做了替换，也可以大幅度提升业务的响应力和交付质量。</p><p>对于运营效率来说，Refactor/Rearchitect 和 Rebuild/Replace 都可以提升价值流效率。而要想改善客户洞见，最有效的方式还是 Rebuild/Replace。在系统韧性与弹性方面，Rehost 显然是不二之选。</p><p>我们要结合当前遗留系统的现状和想要提升的目标，做综合判断，对于不同的模块，也可以选择不同的策略组合，来实现一个完整的业务目标。</p><p>比如遗留系统中的有些业务，需要提供 7x24 小时的高可用服务，类似银行转账、保险报案等模块。但这些模块很有可能还位于单体的“大泥球”中，和其他模块有着剪不断、理还乱的关系。</p><p>为了支撑这些需求，我们可以先采用 Rearchitect 的模块化策略，结解耦模块之间的关系；然后再用 Rearchitect 的服务化策略，将这些模块拆分成独立的服务；最后再用 Rehost 策略将这些服务部署到云上，以提升系统的可用性。</p><p>当然，如果由于系统耦合严重，模块化改造很难实施，你也可以选择用 Rebuild 策略重写这一部分模块。</p><p>再比如一个部署在 WAS v6 上的 Java Web 遗留系统，由于只支持 Java EE 1.4，技术栈严重落后，已经很难在市场上招到人来维护了。</p><p>这时，可以先选择 Replatform 策略，将 WAS 替换为较新版本的 Tomcat，以摆脱昂贵的商业软件；然后再次使用 Replatform 升级 Java 的版本，包括所依赖的第三方工具，这样就完成了整个技术栈的升级。</p><p>如果企业认为当前遗留系统已经彻底无法满足业务的需要，且具备足够的资源来构建新的系统，就可以使用 Replace 策略来彻底替换旧系统。同时，在遗留系统并不是很大，但重要性又相对很高的情况下，也可以考虑 Rebuild/Replace。</p><p>这里我一直没有提 Encapsulate 这种策略，是因为它有自己独特的适用场景，也就是与其他外部系统集成的时候。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>又到了总结的时刻。今天我们学习了遗留系统现代化的几种策略，不同的策略有不同的适用场景，我把它们总结到了一张表中。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%81%97%E7%95%99%E7%B3%BB%E7%BB%9F%E7%8E%B0%E4%BB%A3%E5%8C%96%E5%AE%9E%E6%88%98/images/07-%25E9%2581%2597%25E7%2595%2599%25E7%25B3%25BB%25E7%25BB%259F%25E7%258E%25B0%25E4%25BB%25A3%25E5%258C%2596%25E7%259A%2584%25E4%25BA%2594%25E7%25A7%258D%25E7%25AD%2596%25E7%2595%25A5/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%81%97%E7%95%99%E7%B3%BB%E7%BB%9F%E7%8E%B0%E4%BB%A3%E5%8C%96%E5%AE%9E%E6%88%98/images/07-%25E9%2581%2597%25E7%2595%2599%25E7%25B3%25BB%25E7%25BB%259F%25E7%258E%25B0%25E4%25BB%25A3%25E5%258C%2596%25E7%259A%2584%25E4%25BA%2594%25E7%25A7%258D%25E7%25AD%2596%25E7%2595%25A5/2.png" alt=""></a></p><p>你要记住的是，一定要根据项目的情况来选择不同的策略组合。不要上来就大张旗鼓地重构或重写，一定要弄清楚想要的是什么。除了重构和重写，你其实还有很多选择。</p><p>从下节课开始，我们马上进入各种模式的学习了，你准备好了吗？</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>感谢你学完了今天的内容。我给你留的作业是这样的：</p><p>假设你是一个项目的技术负责人，你的项目基于.NET Framework 4.6.1，而该版本即将在这个月（2022 年 4 月）“寿终正寝”。为了避免潜在的安全风险，你不得不将.NET 版本进行升级（假设系统当前部署在 Windows 虚拟机上）。</p><p>这时你有以下三个选择：</p><ol><li><p>升级到.NET Framework 4.6.2 版本，几乎不用对代码做任何修改，只需要升级一下各个部署环境的虚拟机即可，保守估计三天之内也能完成升级并上线。</p></li><li><p>升级到最新的.NET Fremework 4.8 版本，可以获得更长的技术支持，还能使用新版语言的特性，以提升开发效率。但有些旧的第三方库并不支持 4.8，需要升级或替换。你可能需要两周到一个月的时间来完成全部升级。</p></li><li><p>升级到.NET 5，以充分享受跨平台和容器化的优势，系统也将彻底摆脱 Windows 的束缚。但代码需要改动的地方很多，几乎所有第三方依赖也都需要升级。预计需要五到六个月的时间才能搞定。</p></li></ol><p>你会做出什么样的选择呢？补充一句，如果你不熟悉.NET 的版本和特性，可以自行搜索一下。</p><p>本次作业没有正确答案，在我看来，任何一个选择都是可以接受的。你可以根据自己的思考给出答案，并说明理由。必要的时候，也可以自己添加一些约束条件，来支持自己的选择。</p><p>期待你的分享。如果你觉得今天这节课对你有帮助，别忘了分享给你的同事和朋友，说不定就能帮他解决一个难题。</p>',71)])])}const u=a(r,[["render",i]]);export{d as __pageData,u as default};
